import sys

def calculate_results(n):
    results = []
    total_games = n * (n - 1) // 2
    if n % 2 == 0:
        for i in range(total_games):
            results.append(1 if i < (total_games // 2) else -1)
    else:
        ties = n - 1
        wins = (total_games - ties) // 2
        for i in range(total_games):
            if i < ties:
                results.append(0)
            elif i < ties + wins:
                results.append(1)
            else:
                results.append(-1)
    return results

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    index = 1
    output = []
    for _ in range(t):
        n = int(input[index])
        index += 1
        results = calculate_results(n)
        output.extend(map(str, results))
    print(" ".join(output))

main()
